const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry - East of Nile in Cairo
  // Cairo center approximately at (31.2357, 30.0444)
  // Create a polygon east of the Nile (longitude > 31.25)
  const cairo_east = ee.Geometry.Polygon([
    [[31.25, 30.15],
     [31.50, 30.15],
     [31.50, 29.90],
     [31.25, 29.90],
     [31.25, 30.15]]
  ]);

  // 2. Data Acquisition for 1984 (Landsat 5)
  const col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(cairo_east)
    .filterDate('1984-07-01', '1984-07-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1984 = col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log("No Landsat 5 data for July 1984.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Data Acquisition for 2019 (Landsat 8)
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(cairo_east)
    .filterDate('2019-09-01', '2019-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images found: ${size2019}`);

  if (size2019 === 0) {
    console.log("No Landsat 8 data for September 2019.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Cloud masking function for Landsat 5
  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask).multiply(0.0000275).add(-0.2);
  }

  // 5. Cloud masking function for Landsat 8
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    return image.updateMask(qaMask).multiply(0.0000275).add(-0.2);
  }

  // 6. Calculate NDBI (Normalized Difference Built-up Index)
  // NDBI = (SWIR - NIR) / (SWIR + NIR)
  const img1984 = col1984.map(maskL5sr).median();
  const ndbi1984 = img1984.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');

  const img2019 = col2019.map(maskL8sr).median();
  const ndbi2019 = img2019.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');

  // 7. Check valid pixels
  const count1984 = ndbi1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cairo_east,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const count2019 = ndbi2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cairo_east,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`Valid pixels 1984: ${count1984}, 2019: ${count2019}`);

  if (count1984 === 0 || count2019 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Calculate built-up area (pixels with NDBI > 0)
  const builtup1984 = ndbi1984.gt(0);
  const builtup2019 = ndbi2019.gt(0);

  const area1984 = builtup1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cairo_east,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const area2019 = builtup2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: cairo_east,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  console.log(`Built-up pixels 1984: ${area1984}`);
  console.log(`Built-up pixels 2019: ${area2019}`);

  // 9. Validation and Final Answer
  if (area1984 === null || area2019 === null || isNaN(area1984) || isNaN(area2019)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = area2019 - area1984;
  console.log(`Change in built-up pixels: ${increase} (${((increase/area1984)*100).toFixed(1)}%)`);

  if (area2019 > area1984) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
